<?php
function require_open_inventory_date($date){if(!complete_update_ready())return;$date=process_date($date);$q=db()->prepare("SELECT close_date FROM day_closings WHERE status='Closed' AND close_date>=? ORDER BY close_date DESC LIMIT 1");$q->execute([$date]);if($closed=$q->fetchColumn())throw new Exception('Inventory is closed through '.$closed.'. Admin must reopen that cutoff with a reason before backdated posting.');}
function day_action_guard($action,$input){
 $writes=['repack_post','packaging_receive_raw','packaging_complete','save_beginning','confirm_beginning_upload','manual_outflow','add_nonsellable','nonsellable_out','transfer_platform','run_allocation','align_platform_balances','confirm_bulk_inflow','confirm_receipt','return_confirm','confirm_order_review','borrow_issue','borrow_return','borrow_approve_conversion','reversal_approve','apply_inventory_count'];
 if(!in_array($action,$writes,true))return;require_open_inventory_date($input['txn_date']??$input['date']??date('Y-m-d'));
 if(in_array($action,['confirm_bulk_inflow','confirm_receipt'],true)){$q=db()->prepare('SELECT * FROM inflow_batches WHERE id=?');$q->execute([(int)($input['batch_id']??0)]);if($b=$q->fetch()){require_open_inventory_date($b['txn_date']);$r=json_decode($b['result_json']??'[]',true)?:[];foreach($r['bulk_rows']??[] as $row)require_open_inventory_date($row['date']);}}
 if($action==='return_confirm')foreach(json_decode(return_batch((int)$input['batch_id'])['rows_json'],true) as $r)require_open_inventory_date($r['date']);
 if($action==='confirm_order_review'){$b=order_review_batch((int)$input['batch_id']);$data=json_decode($b['result_json'],true);foreach($data['review_rows']??[] as $r)require_open_inventory_date($r['date']??date('Y-m-d'));}
 if($action==='reversal_approve'){$q=db()->prepare('SELECT * FROM transaction_reversals WHERE id=?');$q->execute([(int)$input['request_id']]);if($r=$q->fetch()){$plan=reversal_source($r['source_type'],$r['source_id']);foreach(['inflows','outflows','non_sellable','nonsellable_outflows','transfers'] as $kind)foreach($plan[$kind]??[] as $line)if(!empty($line['txn_date']))require_open_inventory_date($line['txn_date']);}}
}
function day_summary($date){process_date($date);$q=db()->prepare("SELECT COUNT(*) FROM inflow_batches WHERE txn_date<=? AND status IN ('Review','To Review','Pending Review')");$q->execute([$date]);$pending=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM import_batches WHERE DATE(created_at)<=? AND import_type IN ('Orders','Beginning Balance') AND status='Review'");$q->execute([$date]);$pending+=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM process_reconciliations WHERE DATE(created_at)<=? AND status='Review'");$q->execute([$date]);$pending+=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM inventory_count_batches WHERE DATE(created_at)<=? AND status IN ('Pending Review','Review Only','Error')");$q->execute([$date]);$pending+=(int)$q->fetchColumn();if(function_exists('repack_ready')&&repack_ready())$pending+=(int)db()->query("SELECT COUNT(*) FROM repackaging_batches WHERE status='Review' AND txn_date<=".db()->quote($date))->fetchColumn();if(adjustments_ready()){$q=db()->prepare("SELECT COUNT(*) FROM inventory_count_batches WHERE count_date<=? AND workflow_version='5.4.0' AND status IN ('Exported','Recount Required','Recounted','Awaiting Approval')");$q->execute([$date]);$pending+=(int)$q->fetchColumn();}$total=['sellable'=>0,'non_sellable'=>0,'physical'=>0];$negative=0;foreach(db()->query('SELECT id FROM products WHERE active=1') as $p){$s=stock_row($p['id']);$at=adjustments_ready()?inventory_balance_at($p['id'],$date):['sellable'=>$s['current'],'restricted'=>$s['nonsellable'],'physical'=>$s['physical']];$total['sellable']+=$at['sellable'];$total['non_sellable']+=$at['restricted'];$total['physical']+=$at['physical'];check_platform_alignment($p['id']);}foreach(db()->query('SELECT product_id,platform,qty FROM platform_stock') as $p)if((adjustments_ready()?report_platform_balance($p['product_id'],$p['platform'],$date):(int)$p['qty'])<0)$negative++;return $total+['pending'=>$pending,'negative_platforms'=>$negative,'open_exceptions'=>(int)db()->query("SELECT COUNT(*) FROM stock_exceptions WHERE status='Open'")->fetchColumn(),'date'=>$date];}
function day_close($date,$reason,$digest,$ack){return process_transaction(function()use($date,$reason,$digest,$ack){if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');if(!$ack)throw new Exception('Review the closing summary.');$reason=process_reason($reason);$summary=day_summary($date);if(!hash_equals(hash('sha256',json_encode($summary)),$digest))throw new Exception('Closing summary changed. Review again.');if($summary['pending'])throw new Exception('Post or cancel pending uploads/counts before closing.');$q=db()->prepare('SELECT status FROM day_closings WHERE close_date=?');$q->execute([$date]);if($q->fetchColumn()==='Closed')throw new Exception('This cutoff is already closed.');db()->prepare("INSERT INTO day_closings(close_date,status,reason,closed_by,closed_at,summary_json) VALUES(?,'Closed',?,?,NOW(),?) ON DUPLICATE KEY UPDATE status='Closed',reason=VALUES(reason),closed_by=VALUES(closed_by),closed_at=NOW(),summary_json=VALUES(summary_json)")->execute([$date,$reason,current_user()['id'],json_encode($summary)]);daily_closing_archive($date,'Closed',$reason);audit('Close inventory cutoff','Closing',$date,$reason.'; Sellable '.$summary['sellable'].'; Non-Sellable '.$summary['non_sellable'].'; Physical '.$summary['physical'].'; Negative platforms '.$summary['negative_platforms']);});}
function day_reopen($date,$reason){return process_transaction(function()use($date,$reason){if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');$reason=process_reason($reason);$q=db()->prepare("UPDATE day_closings SET status='Reopened',reason=CONCAT(reason,?) WHERE close_date=? AND status='Closed'");$q->execute(["\nReopened: ".$reason,$date]);if(!$q->rowCount())throw new Exception('Closed cutoff not found.');daily_closing_archive($date,'Reopened',$reason);audit('Reopen inventory cutoff','Closing',$date,$reason);});}
function record_stock_event($platform,$pid,$before,$after){if(!complete_update_ready()||$before===$after)return;$ctx=$GLOBALS['RS8_STOCK_CONTEXT']??[];db()->prepare('INSERT INTO stock_events(txn_date,platform,product_id,before_qty,after_qty,reference_no,action_type,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$ctx['date']??date('Y-m-d'),$platform,$pid,$before,$after,substr($ctx['ref']??($_POST['order_id']??$_POST['reference_no']??''),0,100),substr($GLOBALS['RS8_REPORT_ACTION']??$_POST['action']??$ctx['action']??'Platform balance change',0,60),current_user()['id']?:null]);}
